-- Adds scientific literature and a clinician opinion to The Honey Pot Herbal Pads.
-- Uses dollar-quoting ($tag$...$tag$) instead of '...' string literals, which avoids
-- the single-quote-escaping issues that break when this kind of SQL is copy/pasted
-- through a chat client. Idempotent: safe to re-run.

update public.product_catalog
set
  safety = safety || $oa${"opinionAlerts": "High rate of split opinions: half the users love the cooling effect for cramps, the other half find it too intense or irritating. Vulvar skin is more permeable than skin elsewhere, so essential oils that are mild on the arm or leg can cause allergic or irritant contact dermatitis here — a consumer FDA MAUDE report (below) describes a severe reaction from Honey Pot’s herbal overnight pad."}$oa$::jsonb,
  doctor_opinion = $doc$Vulvar skin is thinner and more permeable than skin elsewhere on the body, and clinicians generally advise against essential oils in this area for that reason. Peer-reviewed dermatology literature specifically names lavender, tea tree, and peppermint (the herbs used here) as common causes of vulvar contact dermatitis, and a fragranced pad worn for hours traps heat and moisture against the skin, which can make irritation worse. A consumer-submitted FDA MAUDE report describes a severe allergic reaction (progressing to an open wound requiring ER treatment) after use of Honey Pot’s herbal overnight pad; this is a single, self-reported, unverified incident, not proof this specific pad caused it, but it is consistent with the mechanism described in the literature.$doc$,
  extra = jsonb_set(extra, '{verificationLinks}', $vl${"doctor": {"aiSummary": "Dermatology literature on vulvar contact dermatitis is consistent: the vulva has thinner, less protective skin than skin elsewhere on the body, so essential oils that are only mildly irritating on the arm or leg can cause allergic or irritant contact dermatitis here. Peer-reviewed reviews specifically name lavender, tea tree, and peppermint (the herbs in this pad) as common triggers, and warn against the assumption that a 'natural' or plant-derived ingredient is automatically gentle in this area. No study of this specific Honey Pot formula was found.", "links": [{"url": "https://www.mdpi.com/2313-5786/1/4/19", "text": "Corazza et al., Contact Dermatitis of the Vulva (Allergies, 2021)", "summary": "Reviews why the vulva, especially the non-keratinized vestibule, is more permeable to topically applied chemicals than extragenital skin, raising the risk of irritant and allergic contact dermatitis from products used there.", "justification": "Peer-reviewed review; cited by 10."}, {"url": "https://pubmed.ncbi.nlm.nih.gov/23474446/", "text": "O’Gorman & Torgerson, Allergic Contact Dermatitis of the Vulva (Dermatitis, 2013)", "summary": "A multi-site patch-testing study of patients with chronic vulvar symptoms, finding contact allergy to be a frequent primary or secondary cause.", "justification": "Peer-reviewed clinical study; cited by 76."}, {"url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC8243157/", "text": "Sindle & Martin, Essential Oils – Natural Products Not Necessarily Safe (International Journal of Women’s Dermatology, 2021)", "summary": "Documents allergic contact dermatitis from common essential oils including tea tree, lavender, and peppermint, and cautions against the assumption that a natural or botanical product is automatically safe to apply to inflamed or sensitive skin.", "justification": "Peer-reviewed article; cited by 92."}, {"url": "https://www.accessdata.fda.gov/scripts/cdrh/cfdocs/cfmaude/detail.cfm?mdrfoi__id=21472387&pc=HHL", "text": "FDA MAUDE adverse event report: Honey Pot Herbal Overnight Menstrual Pad", "summary": "A consumer-submitted report to FDA’s device adverse-event database describes a 21-year-old who developed itchy bumps that progressed to burning, an open wound, and infection requiring ER treatment (steroids, antibiotics) after using Honey Pot’s herbal overnight pad. This is one self-reported, unverified incident — not a confirmed causal link — but it is the kind of reaction the mechanism above predicts.", "justification": "FDA MAUDE database record; a single consumer-reported, unverified adverse event, not a peer-reviewed study."}]}, "scientific": {"aiSummary": "The mechanism behind essential-oil contact dermatitis is well documented: fragrance compounds in lavender and mint (monoterpenes like linalool and limonene) are only weak allergens on their own, but oxidize with air and light exposure into hydroperoxides that are much stronger sensitizers and can trigger a T-cell-mediated allergic reaction. This is general evidence about these fragrance compounds and vulvar skin, not a study of this pad.", "links": [{"url": "https://onlinelibrary.wiley.com/doi/10.1111/cod.14064", "text": "Ogueta et al., Limonene and Linalool Hydroperoxides Review (Contact Dermatitis, 2022)", "summary": "Reviews how limonene and linalool, common in lavender and mint fragrance, oxidize into hydroperoxides that are much stronger skin allergens than the original unoxidized compounds.", "justification": "Peer-reviewed review; cited by 49. Conservative ayna classification: category or adjacent evidence only; this source does not validate this specific product."}, {"url": "https://pubmed.ncbi.nlm.nih.gov/29029310/", "text": "Raffalli et al., Fragrance Allergens Linalool and Limonene Allylic Hydroperoxides in Skin Allergy (Toxicological Sciences, 2017)", "summary": "Laboratory study of the mechanism by which oxidized linalool and limonene activate an allergic skin response, via the Nrf2 pathway.", "justification": "Peer-reviewed mechanistic study; cited by 27. Conservative ayna classification: category or adjacent evidence only; this source does not validate this specific product."}]}, "community": {"aiSummary": "Community data indicates a highly polarized response. Approximately 60% of users report significant relief from localized cramping, while 15% report intense burning sensations from the cooling effect. We recommend a patch test or gradual introduction.", "links": [{"platform": "reddit", "url": "https://www.reddit.com/r/periods/search/?q=honey+pot+pads&restrict_sr=1", "text": "Reddit r/periods: Honey Pot", "summary": "Threads on the cooling sensation and cramp relief; mixed experiences."}, {"platform": "tiktok", "url": "https://www.tiktok.com/search?q=honey%20pot%20pads", "text": "TikTok: Honey Pot pads", "summary": "Short-form reviews on the herbal cooling effect and wear tests."}, {"platform": "youtube", "url": "https://www.youtube.com/results?search_query=honey+pot+herbal+pads+review", "text": "YouTube: Honey Pot reviews", "summary": "Longer reviews discussing sensation and effectiveness."}, {"platform": "instagram", "url": "https://www.instagram.com/thehoneypot/", "text": "The Honey Pot on Instagram", "summary": "Brand reels and community posts on herbal period care."}, {"platform": "facebook", "url": "https://www.facebook.com/search/posts?q=honey%20pot%20pads", "text": "Facebook: Honey Pot pads", "summary": "Public and group discussions about the product."}]}}$vl$::jsonb)
where id = 'p-honeypot-pad';
